def unique_jobs(rows):
    seen = {}
    # key (source, source_id) where source_id is not None/empty? 
    # Only dedup when source_id exists and is not None/empty? 
    # Requirement: Missing/None/empty source_id means keep the row separately.
    # So if source_id is None or '' treat as unique key automatically.
    # Use (source, source_id) tuple as key only when source_id is not None and source_id != ''
    # Otherwise use (source, None) but that would dedup? No, treat separately -> no dedup.
    # We'll store rows and only skip if we have seen same (source, source_id) with non-empty/non-None.
    # Also keep order of first occurrence.
    seen_key_to_index = {}
    result = []
    for r in rows:
        key = None
        if 'source_id' in r:
            source_id = r['source_id']
            if source_id is not None and source_id != '':
                key = (r['source'], source_id)
        if key is None:
            # missing/None/empty source_id -> always keep
            result.append(r)
        else:
            if key in seen_key_to_index:
                # duplicate within same source/id, skip
                continue
            else:
                seen_key_to_index[key] = len(result)  # store index
                result.append(r)
    return result
